#!/bin/bash
# ============================================================
# Yuzhou Crystal 最终部署脚本 v3
# 修复内容：
#   1. yuzhoucrystal.html 彻底修复（此前被误插入损坏）
#   2. Contact 为首页独立 section（锚点 #contact）
#   3. Atelier 工厂画廊 + 客户评价(带国籍) + 联系表单
#   4. 导航高亮正确：About 不再误高亮 Contact
#   5. 所有 section 标题文字居中对齐（Collections/Custom/Capabilities）
# 用法：
#   在 VPS 上：  bash deploy_final3.sh
#   然后执行：  sudo docker compose up -d --build --force-recreate
# ============================================================
set -e
cd /home/admin/yuzhou-inquiry/public

echo "==> 备份现有文件 =="
ts=$(date +%s)
cp index.html index.html.bak.$ts 2>/dev/null || true
cp yuzhoucrystal.html yuzhoucrystal.html.bak.$ts 2>/dev/null || true
mkdir -p images/factory

echo "==> 解压新文件到 public/ =="
base64 -d << 'B64EOF' | tar xzf -

B64EOF

echo "==> 校验解压结果 =="
echo "index.html      行数: $(wc -l < index.html) 大小: $(du -h index.html | cut -f1)"
echo "yuzhoucrystal.html 行数: $(wc -l < yuzhoucrystal.html) 大小: $(du -h yuzhoucrystal.html | cut -f1)"
echo "factory 图片: $(ls images/factory/ | wc -l) 张"
echo "所有 sec-head 居中检测: $(grep -c 'sec-head center' index.html) 处 (index) / $(grep -c 'sec-head center' yuzhoucrystal.html) 处 (yuzhou)"

echo ""
echo "============================================================"
echo " 文件已更新。请执行以下命令重建 Docker 容器使改动生效："
echo ""
echo "  cd /home/admin/yuzhou-inquiry"
echo "  sudo docker compose up -d --build --force-recreate"
echo "============================================================"
